<template><section><div class="head"><h2>回答反馈</h2><el-button @click="load">刷新</el-button></div><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option label="待处理" value="pending"/><el-option label="已分诊" value="triaged"/><el-option label="已解决" value="resolved"/><el-option label="已忽略" value="ignored"/></el-select><el-table :data="items" style="margin-top:12px"><el-table-column prop="rating" label="评价" width="90"/><el-table-column prop="reason_code" label="原因" width="120"/><el-table-column prop="comment" label="补充意见" min-width="220"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="created_at" label="时间" width="180"/><el-table-column label="操作" width="250"><template #default="{row}"><el-button link @click="act(row,'triage')">分诊</el-button><el-button link type="success" @click="act(row,'resolve')">解决</el-button><el-button link @click="act(row,'ignore')">忽略</el-button><el-button link type="warning" :disabled="row.evaluation_candidate" @click="candidate(row)">转评测候选</el-button></template></el-table-column></el-table></section></template>
<script setup lang="ts">import{onMounted,ref}from"vue";import{ElMessage,ElMessageBox}from"element-plus";import{addEvaluationCandidate,listFeedback,transitionFeedback}from"../../../api/conversation/feedback";import type{AnswerFeedback}from"../../../types";const items=ref<AnswerFeedback[]>([]),status=ref("pending");async function load(){try{items.value=(await listFeedback(status.value?{status:status.value}:{})).items}catch(e){ElMessage.error((e as Error).message)}}async function act(row:AnswerFeedback,a:"triage"|"resolve"|"ignore"){try{const{value}=await ElMessageBox.prompt("填写处理说明","反馈处理",{inputType:"textarea"});await transitionFeedback(row.id,a,value);await load()}catch{/* 取消 */}}async function candidate(row:AnswerFeedback){try{await addEvaluationCandidate(row.id);ElMessage.success("已脱敏加入评测候选池");await load()}catch(e){ElMessage.error((e as Error).message)}}onMounted(load);</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center}</style>
